"""Full RL Agent for Kaggriculture.

Bypasses all heuristic logic and directly outputs atomic actions
predicted by the PyTorch Behavior Cloning model.
"""

import base64
import io
import sys

import numpy as np

"""Full RL Action Space Encodings."""


# Farmer / Hand Actions
BASE_ACTIONS = ["PASS", "N", "S", "E", "W", "WATER", "HARVEST", "DEMOLISH"]
PLACE_ITEMS = [
    "WHEAT",
    "CARROT",
    "TOMATO",
    "STRAWBERRY",
    "MELON",
    "GOOSE",
    "COW",
    "SHEEP",
    "COOP",
    "PASTURE",
]
FARMER_ONLY = ["HIRE", "BUY_LAND"]

ALL_UNIT_ACTIONS = BASE_ACTIONS + [f"PLACE_{item}" for item in PLACE_ITEMS]
ALL_FARMER_ACTIONS = ALL_UNIT_ACTIONS + FARMER_ONLY

UNIT_ACTION_MAP = {act: i for i, act in enumerate(ALL_UNIT_ACTIONS)}
FARMER_ACTION_MAP = {act: i for i, act in enumerate(ALL_FARMER_ACTIONS)}

NUM_UNIT_ACTIONS = len(ALL_UNIT_ACTIONS)
NUM_FARMER_ACTIONS = len(ALL_FARMER_ACTIONS)

# Market Actions
MARKET_ITEMS = [
    "WHEAT",
    "CARROT",
    "TOMATO",
    "STRAWBERRY",
    "MELON",
    "EGG",
    "MILK",
    "WOOL",
    "FERTILIZER",
    "GOOSE",
    "COW",
    "SHEEP",
]
MARKET_ITEM_MAP = {item: i for i, item in enumerate(MARKET_ITEMS)}
NUM_MARKET_ITEMS = len(MARKET_ITEMS)


def encode_unit_action(action_list, is_farmer=False):
    """Encode a unit action list e.g. ['PLACE', 'WHEAT'] into an integer class."""
    if not action_list:
        return 0  # PASS

    act_str = action_list[0]
    if act_str == "PLACE" and len(action_list) > 1:
        act_str = f"PLACE_{action_list[1]}"

    m = FARMER_ACTION_MAP if is_farmer else UNIT_ACTION_MAP
    return m.get(act_str, 0)  # Default to PASS if unknown


def decode_unit_action(class_idx, is_farmer=False):
    """Decode integer class back to action list e.g. ['PLACE', 'WHEAT']."""
    actions = ALL_FARMER_ACTIONS if is_farmer else ALL_UNIT_ACTIONS
    if class_idx < 0 or class_idx >= len(actions):
        return ["PASS"]

    act_str = actions[class_idx]
    if act_str.startswith("PLACE_"):
        return ["PLACE", act_str.split("_")[1]]
    return [act_str]


def encode_market_actions(market_orders):
    """
    Encode market orders into a fixed tensor of shape (NUM_MARKET_ITEMS, 3).
    Channels: [buy_flag, sell_flag, log_qty]
    """
    tensor = np.zeros((NUM_MARKET_ITEMS, 3), dtype=np.float32)
    for order in market_orders:
        if not order or len(order) < 3:
            continue
        op, item, qty = order
        if item not in MARKET_ITEM_MAP:
            continue
        idx = MARKET_ITEM_MAP[item]

        if op == "BUY_PRODUCT":
            tensor[idx, 0] = 1.0
        elif op == "SELL":
            tensor[idx, 1] = 1.0

        tensor[idx, 2] = np.log1p(qty)
    return tensor


def decode_market_actions(tensor):
    """
    Decode market tensor (NUM_MARKET_ITEMS, 3) back to list of orders.
    Threshold for buy/sell is > 0.5. If both > 0.5, take the max.
    """
    orders = []
    for idx, item in enumerate(MARKET_ITEMS):
        buy_logit = tensor[idx, 0]
        sell_logit = tensor[idx, 1]
        log_qty = tensor[idx, 2]

        if buy_logit < 0.5 and sell_logit < 0.5:
            continue

        qty = int(np.expm1(log_qty))
        if qty <= 0:
            continue

        if buy_logit > sell_logit:
            orders.append(["BUY_PRODUCT", item, qty])
        else:
            orders.append(["SELL", item, qty])

    return orders


def _relu(x):
    return np.maximum(0, x)


def _maxpool2d_np(x, size=2):
    C, H, W = x.shape
    out_H = H // size
    out_W = W // size
    return x.reshape(C, out_H, size, out_W, size).max(axis=(2, 4))


def _conv2d_np(x, w, b, padding=1, stride=1):
    C_in, H, W = x.shape
    C_out, _, kH, kW = w.shape
    out_H = (H + 2 * padding - kH) // stride + 1
    out_W = (W + 2 * padding - kW) // stride + 1
    if padding > 0:
        x_pad = np.pad(x, ((0, 0), (padding, padding), (padding, padding)), mode="constant")
    else:
        x_pad = x
    out = np.zeros((C_out, out_H, out_W), dtype=np.float32)
    for i in range(out_H):
        for j in range(out_W):
            x_slice = x_pad[:, i * stride : i * stride + kH, j * stride : j * stride + kW]
            out[:, i, j] = np.sum(x_slice * w, axis=(1, 2, 3)) + b
    return out


class NumpyPolicyFullRL:
    def __init__(self, weights_dict):
        self.w = weights_dict

    def _linear(self, name, x):
        return np.dot(self.w[f"{name}.weight"], x) + self.w[f"{name}.bias"]

    def _conv2d(self, name, x, padding=1, stride=1):
        return _conv2d_np(x, self.w[f"{name}.weight"], self.w[f"{name}.bias"], padding, stride)

    def __call__(self, vector_obs, spatial_obs):
        # vector_obs: (4,)
        # spatial_obs: (5, 10, 10)

        # 1. Observation Encoder
        v = self._linear("encoder.vector_mlp.0", vector_obs)
        v = _relu(v)
        v = self._linear("encoder.vector_mlp.2", v)

        s = self._conv2d("encoder.spatial_cnn.0", spatial_obs, padding=1)
        s = _relu(s)
        s = _maxpool2d_np(s, 2)
        s = self._conv2d("encoder.spatial_cnn.3", s, padding=1)
        s = _relu(s)

        s_flat = s.flatten()
        s_proj = self._linear("encoder.spatial_proj", s_flat)

        state_emb = v + s_proj

        # 2. Farmer Head
        f = self._linear("farmer_head.net.0", state_emb)
        f = _relu(f)
        f_logits = self._linear("farmer_head.net.2", f)

        # 3. Market Head
        m = self._linear("market_head.net.0", state_emb)
        m = _relu(m)
        m_preds = self._linear("market_head.net.2", m)
        m_preds = m_preds.reshape((12, 3))

        # 4. Hands Spatial Head
        v_grid = np.broadcast_to(vector_obs[:, None, None], (4, 10, 10))
        x_hands = np.concatenate([spatial_obs, v_grid], axis=0)

        h = self._conv2d("hands_head.conv_net.0", x_hands, padding=1)
        h = _relu(h)
        h = self._conv2d("hands_head.conv_net.2", h, padding=1)
        h = _relu(h)
        h_logits = self._conv2d("hands_head.conv_net.4", h, padding=0)

        return f_logits, h_logits, m_preds


AGENT_VERSION = "0.0.8"


_BC_WEIGHTS_B64 = ""

_POLICY = None


def _load_model():
    global _POLICY
    if _POLICY is not None:
        return

    try:
        with np.load(io.BytesIO(base64.b64decode(_BC_WEIGHTS_B64))) as data:
            weights = {k: data[k] for k in data.files}
        _POLICY = NumpyPolicyFullRL(weights)
    except Exception as e:
        print(f"Failed to load numpy weights: {e}", file=sys.stderr)


def _extract_features(obs, player):
    """Extract spatial and vector features for the current step."""
    farms = obs.get("farms", [])
    if player >= len(farms):
        return None, None

    farm = farms[player]

    grid_planes = np.zeros((5, 10, 10), dtype=np.float32)
    crop_map = {"WHEAT": 1, "STRAWBERRY": 2, "MELON": 3}

    tiles = farm.get("tiles", [])
    for i, row in enumerate(tiles):
        for j, tile in enumerate(row):
            if tile == "LOCKED":
                grid_planes[0, i, j] = 1.0
            elif tile == "EMPTY":
                grid_planes[1, i, j] = 1.0
            elif isinstance(tile, dict) and tile.get("kind") == "PLANT":
                ctype = crop_map.get(tile.get("crop", ""), 0)
                grid_planes[2, i, j] = ctype
                grid_planes[3, i, j] = tile.get("yield_units", 0)
                grid_planes[4, i, j] = 1.0 if tile.get("watered_today") else 0.0

    day = float(obs.get("day", 0)) / 30.0
    hour = float(obs.get("hour", 0)) / 24.0
    money = float(farm.get("money", 0.0)) / 10000.0

    hands_list = farm.get("hands", []) or []
    hands_count = len(hands_list) / 24.0

    g_vec = np.array([day, hour, money, hands_count], dtype=np.float32)

    return grid_planes, g_vec


def agent(obs, config=None):
    """Kaggriculture entrypoint for Full RL Agent."""
    try:
        step = int(obs.get("step", 0) or 0)
        if step == 0:
            print(f"Kaggriculture Agent v{AGENT_VERSION}")

        _load_model()
        player = int(obs.get("player", 0) or 0)

        spatial_feat, vector_feat = _extract_features(obs, player)
        if spatial_feat is None:
            return {"farmer": ["PASS"], "hands": [], "market": []}

        f_logits, h_logits, m_preds = _POLICY(vector_feat, spatial_feat)

        f_idx = int(np.argmax(f_logits))
        farmer_action = decode_unit_action(f_idx, is_farmer=True)

        h_preds = np.argmax(h_logits, axis=0)

        hands_list = obs.get("farms", [])[player].get("hands", [])
        hands_actions = []

        for x, y in hands_list:
            if 0 <= x < 10 and 0 <= y < 10:
                h_idx = h_preds[y, x]
                act = decode_unit_action(h_idx, is_farmer=False)
                hands_actions.append(act)
            else:
                hands_actions.append(["PASS"])

        m_tensor = m_preds
        market_orders = decode_market_actions(m_tensor)

        return {
            "farmer": farmer_action,
            "hands": hands_actions,
            "market": market_orders[:10],  # Hard limit of 10 orders per turn
        }

    except Exception as e:
        print(f"Exception in agent: {e}", file=sys.stderr)
        return {"farmer": ["PASS"], "hands": [], "market": []}
